let s, shader_graphic;
let img, img_ratio;
let music, fft;

function preload() {
	img = loadImage('https://openprocessing.org/sketch/1589321/files/20220412_144559.jpg');
	// music_link = 'https://deckard.openprocessing.org/user304894/visual1452945/hb570e68247d1cce4f328d7cc3f8009c2/999999999-x0004000x-ntnltd001x.mp3';
	//music_link = 'https://deckard.openprocessing.org/user193927/visual1230472/hb871491923457f18fbca3aad0a01413a/mos-def-crime-medicine.mp3';
	// music_link = 'https://deckard.openprocessing.org/user193927/visual1230487/h42be480d836896a17106a08d7dadf950/aap-rocky-sundress.mp3';
  music = loadSound(music_link);
}

function setup() {
	pixelDensity(1);
  createCanvas(windowWidth, windowHeight, WEBGL);
	noStroke();

	img_ratio = img.width / img.height;

  s = createShader(vert, frag);
	shader(s);

  noLoop();
  fft = new p5.FFT();
  fft.setInput(music);
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  redraw();
}

function mousePressed() {
  if (music.isPlaying())
  {
    music.pause();
    noLoop();
  }
  else
  {
    music.loop();
    loop();
  }
}

function draw() {
	fft.analyze();

  const bass = fft.getEnergy("bass") / 255;
  const treble = fft.getEnergy("treble") / 255;
  const mid = fft.getEnergy("mid") / 255;


  s.setUniform("iResolution", [width, height]);
  s.setUniform("iMouse", [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))]);
  s.setUniform("iTime", millis() * 0.001);

  s.setUniform("iChannel0", img);
  s.setUniform("iChannel0Ratio", img_ratio);

  s.setUniform('iBass', bass);
  s.setUniform('iTreble', treble);
  s.setUniform('iMid', mid);

  rect(0, 0, width, height);
	// console.log(frameRate())
}

