let frag = `
precision highp float;

uniform float iTime;
uniform vec2 iResolution;
uniform vec2 iMouse;

uniform sampler2D iChannel0;
uniform float iChannel0Ratio;

uniform float iBass;
uniform float iTreble;
uniform float iMid;

#define MAX_STEPS 100
#define MAX_DIST 100.
#define MIN_DIST 0.001

#define PI 3.141592
#define TAU 2. * PI

float sd_sphere(vec3 p, float s)
{
  return length(p)-s;
}

float sd_box(vec3 p, vec3 b)
{
  vec3 q = abs(p) - b;
  return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0);
}

float sd_round_box(vec3 p, vec3 b, float r)
{
  vec3 q = abs(p) - b;
  return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0) - r;
}

float sd_vertical_capsule(vec3 p, float h, float r)
{
  p.y -= clamp(p.y, 0.0, h);
  return (length(p) - r);
}

float sd_box_frame(vec3 p, vec3 b, float e)
{
       p = abs(p)-b;
  vec3 q = abs(p+e)-e;
  return min(min(
      length(max(vec3(p.x,q.y,q.z),0.0))+min(max(p.x,max(q.y,q.z)),0.0),
      length(max(vec3(q.x,p.y,q.z),0.0))+min(max(q.x,max(p.y,q.z)),0.0)),
      length(max(vec3(q.x,q.y,p.z),0.0))+min(max(q.x,max(q.y,p.z)),0.0));
}

float sd_torus(vec3 p, vec2 t)
{
  vec2 q = vec2(length(p.xz)-t.x,p.y);
  return length(q)-t.y;
}

vec2 smin(vec2 s_pow, vec2 b, float k)
{
    float h = max(k - abs(s_pow.x - b.x), 0.0);
    float s = min(s_pow.x, b.x) - h*h*h/(6.0*k*k);
    return (s_pow.x < b.x) ? vec2(s, s_pow.y) : vec2(s, b.y);
}

vec2 op_union(vec2 s_pow, vec2 b)
{
    return (s_pow.x < b.x) ? s_pow : b;
}

vec2 op_intersection(vec2 s_pow, vec2 b)
{
    return (s_pow.x >= b.x) ? s_pow : b;
}

vec2 op_substract(vec2 s_pow, vec2 b)
{
    s_pow.x *= -1.;
    return op_intersection(s_pow, b);
}

vec2 op_blend(vec2 s_pow, vec2 b)
{
    float m = smin(s_pow, b, 0.5).x;
    return vec2(m, (s_pow.x < b.x) ? s_pow.y : b.y);
}

mat2 rot(float s_pow)
{
    return mat2(cos(s_pow), -sin(s_pow), sin(s_pow), cos(s_pow));
}

mat3 rotateY(float r)
{
    vec2 cs = vec2(cos(r), sin(r));
    return mat3(cs.x, 0, cs.y, 0, 1, 0, -cs.y, 0, cs.x);
}

mat3 rotateZ(float r)
{
    vec2 cs = vec2(cos(r), sin(r));
    return mat3(cs.x, cs.y, 0., -cs.y, cs.x, 0., 0., 0., 1.);
}

vec2 speaker(vec3 p, vec2 w, float i, vec2 modifier)
{
	vec3 ppp = p * rotateZ(0.) - vec3(0., 0.2 + i * modifier.x, 0);
	float o = modifier.y; //cos(iTime - i) + sin(iTime - i);
	vec2 torus = vec2(sd_torus(ppp, vec2(modifier.y, 0.02 + modifier.x * 0.05)), i);
	return op_blend(torus, w);
}

vec2 map(vec3 p)
{
    vec2 w;
    // map
    p.x = abs(p.x);
    p -= vec3(4, 0, 0);
    p *= rotateZ(1.1);
    vec3 pr = p - vec3(0, 1, 0.);
    vec2 cut = vec2(dot(pr, normalize(vec3(0, 3, .5))), 0.);
    vec2 sphere = vec2(abs(length(pr) - 1.5) - 0.05) * 0.5;
    w = op_intersection(cut, sphere);
		w = op_union(vec2(sd_vertical_capsule(p * rotateZ(-3.1) + vec3(1.45, 6., 0.5), 5., 0.05), 0.), w);
		w = op_union(vec2(sd_vertical_capsule(p * rotateZ(-1.1) + vec3(4., -3.2, 0.5), 1., 0.05), 0.), w);

		w = speaker(p, w, 1., vec2(iBass, 1.));
		w = speaker(p, w, 2., vec2(iMid, 0.5));
		w = speaker(p, w, 3., vec2(iTreble, 0.3));
		w = op_union(vec2(sd_box_frame(p, p + 0.1 * vec3(iBass, iMid, iTreble), 0.1), 0.), w);
    return (w);
}

vec3 raymarcher(vec3 ro, vec3 rd)
{
    // dist.x = distance made between camera origin and shape found
    // dist.y = ID from shape found for color or texture
    // dist.z = Ambient occlusion
    vec3 dist = vec3(0.);

    for (int i=0; i<MAX_STEPS; i++)
    {
        // march from the origin dist.x times in the camera direction
        vec3 p = ro + rd * dist.x;
        vec2 tmp = map(p);
        dist.x += tmp.x;
        dist.y = tmp.y;

        if (dist.x > MAX_DIST ||  abs(tmp.x) < MIN_DIST)
        {
            dist.z = 1. - float(i) / float(MAX_STEPS-1);
            break ;
        }
    }
    return (dist);
}

vec3 get_normal(vec3 p)
{
    vec2 e = vec2(.001, 0);

    vec3 n = map(p).x - vec3(
        map(p - e.xyy).x,
        map(p - e.yxy).x,
        map(p - e.yyx).x
);
    return (normalize(n));
}

float calcSoftshadow(in vec3 ro, in vec3 rd, in float mint, in float tmax)
{
	float res = 1.0;
    float t = mint;
    float ph = 1e10;

    for(int i=0; i<16; i++)
    {
		float h = map(ro + rd*t).x;
        float y = h*h/(2.0*ph);
        float d = sqrt(h*h-y*y);
        res = min(res, 10.0*d/max(0.0,t-y));
        ph = h;
        t += h;
        if (res<0.001 || t>tmax)
            break;
    }
    res = clamp(res, 0.0, 1.0);
    return (res*res*(3.0-2.0*res));
}

vec3 add_phong_light(vec3 k_d, vec3 k_s, float s_pow, vec3 N, vec3 p, vec3 ro, vec3 light_pos)
{
    // light direction
    vec3 L = normalize(light_pos - p);
    vec3 V = normalize(ro - p);
    vec3 R = normalize(reflect(-L, N));

    // diffuse light
    float ln = dot(L, N);
    if (ln < 0.0)
        return vec3(0.0, 0.0, 0.0);

    float d = length(light_pos - p);
    float attenuation = 1. / (1. + 0.09 * d + 0.3 * d * d);

    // specular light
    vec3 H = normalize(L + V);
    float spec = pow(max(dot(N, H), 0.0), 8.);
    float rv = dot(R, V) * spec;

    ln *= calcSoftshadow(p, L, 0.01, 3.0);
    if (rv < 0.0)
        return attenuation * (k_d * ln);
    return attenuation * (k_d * ln + k_s * pow(rv, s_pow));
}

vec3 get_light_color(vec3 p, vec3 ro, vec3 N, vec3 color)
{
    vec3 light1_pos = vec3(4.0 * sin(iTime), 4.0, 4.0 * cos(iTime));
    color += add_phong_light(vec3(1.0, 0.9804, 0.7333), vec3(1.), 100.,
        N, p, ro, light1_pos);

    vec3 light2_pos = vec3(2.0 * sin(0.37 * iTime), 3., 2.0 * cos(0.37 * iTime));
    color += add_phong_light(vec3(1.0, 0.9608, 0.4353), vec3(0.9137, 0.9059, 0.4196), 50.,
        N, p, ro, light2_pos);
    return color * 1.;
}


vec3 pal(in float t, in vec3 a, in vec3 b, in vec3 c, in vec3 d)
{
	return (a + b * cos(6.28318*(c*t+d)));
}

vec3 spectrum(float n, vec3 m)
{
// refer to iq's palette
// 	classic rainbow = vec3(0.0,0.33,0.67)
	return pal(n, vec3(0.5,0.5,0.5), vec3(0.5,0.5,0.5), vec3(1.0,1.0,1.0), m);
}

vec3 get_color(vec3 p, vec3 ro, vec2 id)
{
    vec3 N = get_normal(p);

    if (id.y >= 4.)
        return get_light_color(p, ro, N, spectrum(id.x * 0.2, vec3(0.0,0.33,0.67)));
    if (id.y >= 3.)
        return get_light_color(p, ro, N, spectrum(iTreble, vec3(0.80, 0.90, 0.30)));
    else if (id.y >= 2.)
        return get_light_color(p, ro, N, spectrum(iMid, vec3(0.30, 0.20, 0.20)));
    if (id.y >= 1.)
        return get_light_color(p, ro, N, spectrum(iBass - 0.4, vec3(0.00, 0.10, 0.20))) + vec3(0.1, 0., 0.3);
		else if (id.y >= 0.)
        return get_light_color(p, ro, N, vec3(0.0157, 0.0784, 0.1804));
    return get_light_color(p, ro, N, vec3(0.6078, 0.2392, 0.2392));
}

vec3 get_rd(vec2 st, vec3 p, vec3 l, float z)
{
    vec3 f = normalize(l-p);
    vec3 r = normalize(cross(vec3(0,1,0), f));
    vec3 i = p + f * z + st.x * r + st.y * cross(f, r);
    return (normalize(i - p));
}

float random(vec2 n)
{ 
	return fract(sin(dot(n, vec2(12.9898, 4.1414))) * 43758.5453);
}

vec3 grain(in vec2 st)
{
    float strength = 15.0;
    float x = (st.x + 4.0) * (st.y + 4.0) * (iTime * 10.0);
	return vec3(mod((mod(x, 13.0) + 1.0) * (mod(x, 123.0) + 1.0), 0.01)-0.005) * strength;
}

void main()
{
		vec2 rst = (gl_FragCoord.xy - 0.5 * iResolution.xy) / iResolution.y;
    vec2 st = 1.5 * rst;
    vec2 mouse = iMouse.xy / iResolution.xy;
    vec3 color = vec3(0.0, 0.0, 0.0);

    // camera origin / camera direction
    vec3 ro = vec3(0, 1, 5);
    ro.yz *= rot(-0.5);
    vec3 rd = get_rd(st, ro, vec3(0,1,0), 1.);

    vec3 dist = raymarcher(ro, rd);
    if (dist.x < MAX_DIST - MIN_DIST && dist.x >= 0.)
				color = get_color(ro + dist.x * rd, ro, dist.xy);
		else
		{
				gl_FragColor = vec4(texture2D(iChannel0, vec2(rst.x, -rst.y * iChannel0Ratio) + vec2(0.5)).rgb, 1.);
				return ;
		}
    color = dist.z * pow(color, vec3(.4545));
    gl_FragColor = vec4(color + 0.3 * grain(st), 1.);
}
`

